package api

import (
	"context"
	"encoding/json"
	"net/http"
	"net/url"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/luwa07832/idempotency-gateway/internal/store"
)

// seedExpiredRow writes an expired historical row directly through the store. Each generation is
// committed at a time later than every earlier expiry so overlapping generations for the same key
// are inserted independently while history rows are never mutated.
func seedExpiredRow(t *testing.T, st *store.Store, key, fingerprint, snapshot string, createdAt, expiresAt time.Time) store.Record {
	t.Helper()
	id, err := store.NewRecordID()
	if err != nil {
		t.Fatalf("new id: %v", err)
	}
	record := store.Record{
		ID:                 id,
		IdempotencyKey:     key,
		RequestFingerprint: fingerprint,
		ResponseSnapshot:   []byte(snapshot),
		CreatedAt:          createdAt,
		ExpiresAt:          expiresAt,
	}
	if _, _, err := st.PutRecord(context.Background(), record, createdAt.Add(24*time.Hour)); err != nil {
		t.Fatalf("seed expired row: %v", err)
	}
	return record
}

func historyRouter(t *testing.T) (*store.Store, http.Handler) {
	t.Helper()
	st, err := store.Open(filepath.Join(t.TempDir(), "history.db"))
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	t.Cleanup(func() { st.Close() })
	return st, NewRouter(st)
}

type historyEntry struct {
	ID                 string          `json:"id"`
	IdempotencyKey     string          `json:"idempotency_key"`
	Status             string          `json:"status"`
	RequestFingerprint string          `json:"request_fingerprint"`
	ResponseSnapshot   json.RawMessage `json:"response_snapshot"`
	CreatedAt          string          `json:"created_at"`
	ExpiresAt          string          `json:"expires_at"`
}

type historyPage struct {
	Records    []historyEntry `json:"records"`
	NextCursor string         `json:"next_cursor"`
}

func getHistory(t *testing.T, handler http.Handler, rawQuery string) *http.Response {
