func TestHistoryReturnsExpiredGenerationsOnly(t *testing.T) {
	st, handler := historyRouter(t)
	base := time.Date(2026, 10, 1, 10, 0, 0, 0, time.UTC)

	oldest := seedExpiredRow(t, st, "k1", "fp1", `{"v":1}`, base, base.Add(time.Hour))
	second := seedExpiredRow(t, st, "k1", "fp2", `{"v":2} `, base.Add(2*time.Hour), base.Add(3*time.Hour))
	// Same key, active now: must not appear in history.
	active := store.Record{
		ID:                 func() string { id, _ := store.NewRecordID(); return id }(),
		IdempotencyKey:     "k1",
		RequestFingerprint: "fp3",
		ResponseSnapshot:   []byte(`{"v":3}`),
		CreatedAt:          base.Add(4 * time.Hour),
		ExpiresAt:          base.Add(6 * time.Hour),
	}
	if _, _, err := st.PutRecord(context.Background(), active, base.Add(4*time.Hour)); err != nil {
		t.Fatalf("seed active row: %v", err)
	}
	// Another key's expired row must never leak in.
	seedExpiredRow(t, st, "k2", "fp1", `{"v":9}`, base.Add(time.Minute), base.Add(2*time.Hour))

	response := doJSON(t, handler, http.MethodGet, "/v1/idempotency/history?key=k1", "")
	if response.Code != http.StatusOK {
		t.Fatalf("status = %d body = %s", response.Code, response.Body.String())
	}
	var page historyPage
	if err := json.Unmarshal(response.Body.Bytes(), &page); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(page.Records) != 2 || page.NextCursor != "" {
		t.Fatalf("page = %+v", page)
	}
	if page.Records[0].ID != second.ID || page.Records[1].ID != oldest.ID {
		t.Fatalf("order = [%s %s], want second then oldest", page.Records[0].ID, page.Records[1].ID)
	}
	for _, entry := range page.Records {
		if entry.Status != "expired" {
			t.Fatalf("status = %q, want expired", entry.Status)
		}
		if entry.IdempotencyKey != "k1" {
			t.Fatalf("foreign key leaked: %+v", entry)
		}
	}
	if string(page.Records[0].ResponseSnapshot) != `{"v":2} ` {
		t.Fatalf("snapshot not byte-for-byte: %q", page.Records[0].ResponseSnapshot)
	}
	if string(page.Records[1].ResponseSnapshot) != `{"v":1}` {
		t.Fatalf("first generation snapshot: %q", page.Records[1].ResponseSnapshot)
	}

	// Fixed field order: id, idempotency_key, status, request_fingerprint, response_snapshot,
	// created_at, expires_at.
	body := response.Body.String()
	wantOrder := []string{`"id":"`, `"idempotency_key":"`, `"status":"expired"`, `"request_fingerprint":"`, `"response_snapshot":`, `"created_at":"`, `"expires_at":"`}
	cursor := 0
	for _, fragment := range wantOrder {
		idx := strings.Index(body[cursor:], fragment)
		if idx < 0 {
			t.Fatalf("missing or misordered field %q in %s", fragment, body)
		}
		cursor += idx + len(fragment)
	}

	// Active entry points still hide expired snapshots and keep their original semantics.
	gotRecord := doJSON(t, handler, http.MethodGet, "/v1/idempotency/records/k1", "")
	if gotRecord.Code != http.StatusOK || !strings.Contains(gotRecord.Body.String(), `"status":"active"`) ||
		strings.Contains(gotRecord.Body.String(), `{"v":2}`) {
		t.Fatalf("get-by-key semantics changed: %s", gotRecord.Body.String())
	}
	list := doJSON(t, handler, http.MethodGet, "/v1/idempotency/records?key=k1", "")
	if strings.Count(list.Body.String(), `"idempotency_key"`) != 1 || !strings.Contains(list.Body.String(), active.ID) {
		t.Fatalf("list semantics changed: %s", list.Body.String())
	}
}

func TestHistoryFiltersExactFingerprintAndTimes(t *testing.T) {
	st, handler := historyRouter(t)
