		{"h2", "alpha", time.Minute, time.Hour},
		{"h3", "ALPHA", 2 * time.Minute},
	}
	for _, spec := range specs {
		created := base.Add(spec.created)
		expires := created.Add(time.Hour)
		if spec.name == "h3" {
