		}
		var page historyPage
		if err := json.Unmarshal(response.Body.Bytes(), &page); err != nil {
			t.Fatalf("decode %s: %v", target, err)
		}
		return page
	}

	exact := decode("/v1/idempotency/history?key=k1&request_fingerprint=alpha")
	if len(exact.Records) != 2 || exact.Records[0].ID != rows["h2"].ID || exact.Records[1].ID != rows["h1"].ID {
		t.Fatalf("exact fingerprint page = %+v", exact)
	}
	caseFold := decode("/v1/idempotency/history?key=k1&request_fingerprint=ALPHA")
	if len(caseFold.Records) != 1 || caseFold.Records[0].ID != rows["h3"].ID {
		t.Fatalf("case-sensitive matching = %+v", caseFold)
	}
	prefix := decode("/v1/idempotency/history?key=k1&request_fingerprint=alp")
	if len(prefix.Records) != 0 {
		t.Fatalf("prefix matching leaked: %+v", prefix)
	}
	whitespace := decode("/v1/idempotency/history?key=k1&request_fingerprint=" + url.QueryEscape(" alpha"))
	if len(whitespace.Records) != 0 {
		t.Fatalf("whitespace normalized: %+v", whitespace)
	}

	beforeBoundary := base.Add(90 * time.Minute).Format(time.RFC3339Nano)
	before := decode("/v1/idempotency/history?key=k1&expires_before=" + url.QueryEscape(beforeBoundary))
	if len(before.Records) != 2 {
		t.Fatalf("expires_before strictly before = %d rows", len(before.Records))
	}
	for _, entry := range before.Records {
		if entry.ExpiresAt >= beforeBoundary {
			t.Fatalf("expires_before leaked %q >= %q", entry.ExpiresAt, beforeBoundary)
		}
	}

	equalBoundary := (base.Add(time.Hour)).Format(time.RFC3339Nano)
	atEqual := decode("/v1/idempotency/history?key=k1&expires_after=" + url.QueryEscape(equalBoundary))
	if len(atEqual.Records) != 2 {
		t.Fatalf("expires_after must be strictly after: %d rows", len(atEqual.Records))
	}

	badTime := doJSON(t, handler, http.MethodGet, "/v1/idempotency/history?key=k1&expires_before=not-a-time", "")
	if badTime.Code != http.StatusBadRequest ||
		!strings.HasPrefix(badTime.Body.String(), `{"error":{"code":"invalid_idempotency_record",`) {
		t.Fatalf("bad time = %d %s", badTime.Code, badTime.Body.String())
	}
}

