			t.Fatalf("created_at not RFC 3339: %s", record.CreatedAt)
		}
		if _, err := time.Parse(time.RFC3339, record.ExpiresAt); err != nil {
			t.Fatalf("expires_at not RFC 3339: %s", record.ExpiresAt)
		}
	}
