	if string(parsed.Records[0].ResponseSnapshot) != ` [ "a" , 2 ] ` {
		t.Fatalf("snapshot normalized: %s", parsed.Records[0].ResponseSnapshot)
	}
	if string(parsed.Records[1].ResponseSnapshot) != `{"price":100}` {
		t.Fatalf("first snapshot not verbatim: %s", parsed.Records[1].ResponseSnapshot)
	}
