{"cmd": "cd /mnt/c/anvil/wk09/bench/karlo05 && python3 - <<'PYEOF'
p = 'internal/api/idempotency.go'
s = open(p).read()

# history list envelope + verbatim type, placed after listResponse definition.
anchor = '''type listResponse struct {
	Records    []recordResponse `json:"records"`
	NextCursor string           `json:"next_cursor"`
}'''
addition = anchor + '''

// historyListResponse is the envelope for the expired-record audit query. It uses
// verbatimRecordResponse so the first committed snapshot bytes are emitted untouched: the regular
// encoding/json Marshaler path compacts Marshaler output and would normalize snapshot whitespace.
type historyListResponse struct {
	Records    []verbatimRecordResponse `json:"records"`
	NextCursor string                    `json:"next_cursor"`
}

type verbatimRecordResponse struct {
	recordResponse
}

func (v verbatimRecordResponse) MarshalJSON() ([]byte, error) {
	var b bytes.Buffer
	b.Grow(256 + len(v.ResponseSnapshot))
	b.WriteString(`{"id":`)
	for _, value := range []string{v.ID, v.IdempotencyKey, v.Status, v.RequestFingerprint, v.CreatedAt, v.ExpiresAt} {
		encoded, err := json.Marshal(value)
		if err != nil {
			return nil, err
		}
		b.Write(encoded)
		b.WriteString(`,"`)
	}
	// Rewrite the separators: the loop above is replaced below by explicit fields to lock order.
	b.Reset()

	writeField := func(name, value string, more bool) error {
		b.WriteString(`,"`)
		b.WriteString(name)
		b.WriteString(`":`)
		encoded, err := json.Marshal(value)
		if err != nil {
			return err
		}
		b.Write(encoded)
		_ = more
		return nil
	}
	b.WriteString(`{"id":`)
	encoded, err := json.Marshal(v.ID)
	if err != nil {
		return nil, err
	}
	b.Write(encoded)
	if err := writeField("idempotency_key", v.IdempotencyKey, false); err != nil {
		return nil, err
	}
	if err := writeField("status", v.Status, false); err != nil {
		return nil, err
	}
	if err := writeField("request_fingerprint", v.RequestFingerprint, false); err != nil {
		return nil, err
	}
	b.WriteString(`,"response_snapshot":`)
	snapshot := v.ResponseSnapshot
	if len(snapshot) == 0 {
		snapshot = json.RawMessage("null")
	}
	b.Write(snapshot)
	if err := writeField("created_at", v.CreatedAt, false); err != nil {
		return nil, err
	}
	if err := writeField("expires_at", v.ExpiresAt, false); err != nil {
		return nil, err
	}
	b.WriteString(`}`)
	return b.Bytes(), nil
}'''
assert anchor in s
s = s.replace(anchor, addition, 1)

# Replace the handler's response assembly.
old = '''	response := listResponse{Records: make([]recordResponse, 0, len(records))}
	for i := range records {
		response.Records = append(response.Records, toHistoryRecordResponse(&records[i]))
	}
	response.NextCursor = nextCursor
	c.JSON(http.StatusOK, response)'''
new = '''	response := historyListResponse{Records: make([]verbatimRecordResponse, 0, len(records))}
	for i := range records {
		response.Records = append(response.Records, verbatimRecordResponse{recordResponse: toHistoryRecordResponse(&records[i])})
	}
	response.NextCursor = nextCursor
	c.JSON(http.StatusOK, response)'''
assert old in s
s = s.replace(old, new)

open(p, 'w').write(s)
print("ok")
PYEOF
gofmt -w internal/api/idempotency.go"}

